def alternate_call(
    user: AbstractBloomerpUser, chat: IMConversation, mode: str, client_id: str
) -> dict[str, str]:
    """Demonstrate a provider-owned protocol without invoking conferencing internals."""
    return {
        "provider_call_id": client_id,
        "media_mode": mode,
        "join_url": "/custom/join/",
    }


def audio_only(user: AbstractBloomerpUser, chat: IMConversation) -> IMCallCapabilities:
    """Advertise only audio calls for capability-gating scenarios."""
    return IMCallCapabilities(audio=True)


class TestStartCallComponent(CallFixtures, BloomerpComponentTestCase):
    view_name = "components_im_start_call"

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Cover native initiation, provider hooks, denied membership and retry behavior."""
        return [
            RequestScenario(
                name="Existing call offers an actionable conflict",
                method="POST",
                user=self.normal_user,
                prepare=self.another_start,
                expected=ExpectedResult(
                    status_code=409, response_validators=self.contains_text("Join call")
                ),
            ),
            RequestScenario(
                name="Start a chat call",
                method="POST",
                user=self.normal_user,
                prepare=self.prepare_call,
                expected=ExpectedResult(response_validators=self.persisted_call),
            ),
            RequestScenario(
                name="Login required",
                method="POST",
                prepare=self.prepare_call,
                expected=ExpectedResult(status_code=302),
            ),
            RequestScenario(
                name="GET cannot start calls",
                user=self.normal_user,
                prepare=self.prepare_call,
                expected=ExpectedResult(status_code=405),
            ),
            RequestScenario(
                name="Missing request ID rejected",
                method="POST",
                user=self.normal_user,
                prepare=self.no_request_id,
                expected=ExpectedResult(status_code=400),
            ),
            RequestScenario(
                name="Nonmember superuser rejected",
                method="POST",
                user=self.admin_user,
                prepare=self.nonmember,
                expected=ExpectedResult(status_code=403),
            ),
            RequestScenario(
                name="Provider without calling rejected",
                method="POST",
                user=self.normal_user,
                prepare=self.no_calling,
                expected=ExpectedResult(status_code=400),
            ),
            RequestScenario(
                name="Unsupported video rejected",
                method="POST",
                user=self.normal_user,
                prepare=self.only_audio,
                expected=ExpectedResult(status_code=400),
            ),
            RequestScenario(
                name="Provider owns call protocol",
                method="POST",
                user=self.normal_user,
                prepare=self.custom_provider,
                expected=ExpectedResult(
                    response_validators=self.json_key_equals(
                        "join_url", "/custom/join/"
                    )
                ),
            ),
            RequestScenario(
                name="Duplicate start reuses session",
                method="POST",
                user=self.normal_user,
                prepare=self.replay_start,
                expected=ExpectedResult(response_validators=self.persisted_call),
            ),
            RequestScenario(
                name="Timeout returns retryable response",
                method="POST",
                user=self.normal_user,
                prepare=self.unavailable,
                expected=ExpectedResult(status_code=503),
            ),
        ]

    def persisted_call(self, response: HttpResponse) -> bool:
        """Check invitation persistence without inventing attendance or leaking secrets."""
        import json

        payload = json.loads(response.content)
        session = ConferenceSession.objects.get(pk=UUID(payload["session_id"]))
        return (
            session.status == "ringing"
            and session.participants.count() == 2
            and ConferenceSession.objects.count() == 1
            and "token" not in payload
            and response["Cache-Control"] == "private, no-store"
        )

    def no_request_id(self, scenario: RequestScenario) -> None:
        """Omit idempotency input before dispatch."""
        self.prepare_call(scenario)
        scenario.data.pop("client_id")

    def nonmember(self, scenario: RequestScenario) -> None:
        """Remove the administrator from this private conversation."""
        self.prepare_call(scenario)
        self.peer.delete()

    def no_calling(self, scenario: RequestScenario) -> None:
        """Remove the capability contract from the registered provider."""
        self.prepare_call(scenario)
        provider = replace(
            IM_PROVIDER_REGISTRY.get(self.chat.provider_key), calling=None
        )
        self.provider_patch = patch.dict(
            IM_PROVIDER_REGISTRY._registry, {"INTERNAL": provider}
        )
        self.provider_patch.start()
        scenario.cleanup = self.restore_provider

    def only_audio(self, scenario: RequestScenario) -> None:
        """Advertise an audio-only provider to reject a video request."""
        self.prepare_call(scenario)
        original = IM_PROVIDER_REGISTRY.get(self.chat.provider_key)
        provider = replace(
            original,
            calling=replace(original.calling, capabilities_resolver=audio_only),
        )
        self.provider_patch = patch.dict(
            IM_PROVIDER_REGISTRY._registry, {"INTERNAL": provider}
        )
        self.provider_patch.start()
        scenario.cleanup = self.restore_provider

    def custom_provider(self, scenario: RequestScenario) -> None:
        """Use an alternate registered provider key and its own call handler."""
        self.prepare_call(scenario)
        original = IM_PROVIDER_REGISTRY.get(self.chat.provider_key)
        provider = replace(
            original,
            key="custom_calls",
            calling=replace(original.calling, start_handler=alternate_call),
        )
        self.provider_patch = patch.dict(
            IM_PROVIDER_REGISTRY._registry, {"CUSTOM_CALLS": provider}
        )
        self.provider_patch.start()
        scenario.cleanup = self.restore_provider
        self.chat = IMConversation.objects.create(
            name="Custom", provider_key="custom_calls"
        )
        from bloomerp.models.communication.instant_messaging import (
            IMConversationParticipant,
        )

        IMConversationParticipant.objects.create(
            conversation=self.chat, user=self.normal_user
        )
        scenario.view_kwargs = {"conversation_id": self.chat.pk}

    def replay_start(self, scenario: RequestScenario) -> None:
        """Repeat the original client request after a successful start."""
        self.prepare_session()
        scenario.view_kwargs = {"conversation_id": self.chat.pk}
        scenario.data = {"client_id": "request-1", "media_mode": "video"}

    def another_start(self, scenario: RequestScenario) -> None:
        """Attempt another request while the same conversation already has a call."""
        self.replay_start(scenario)
        scenario.data["client_id"] = "another-request"

    def unavailable(self, scenario: RequestScenario) -> None:
        """Fail at the external transport boundary without losing the reservation."""
        self.prepare_call(scenario)
        self.create_room.side_effect = TimeoutError

    def restore_provider(self, scenario: RequestScenario) -> None:
        """Restore registry contents at the end of each provider override scenario."""
        self.provider_patch.stop()


from bloomerp.models.communication.voip import PhoneCall
from bloomerp.tests.components.communication.voip.fixtures import ComponentFixtures


class TestStartCarrierCall(ComponentFixtures, BloomerpComponentTestCase):
    """Phone calls use the exact same IM start endpoint without conference records."""

    view_name = "components_im_start_call"

    def prepare_audio(self, scenario: RequestScenario) -> None:
        """Create an authorized voice line and a shared-contract audio request."""
        self.prepare_request(scenario)
        scenario.view_kwargs = {"conversation_id": self.chat.pk}
        scenario.data = {"client_id": "unified", "media_mode": "audio"}

    def prepare_video(self, scenario: RequestScenario) -> None:
        """Request a capability the carrier does not declare."""
        self.prepare_audio(scenario)
        scenario.data["media_mode"] = "video"

    def phone_only(self, response: HttpResponse) -> bool:
        """Keep carrier persistence independent of conferencing models."""
        return PhoneCall.objects.count() == 1 and ConferenceSession.objects.count() == 0

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Exercise shared dispatch while preserving carrier capabilities and persistence."""
        return [
            RequestScenario(
                name="Phone through common start",
                method="POST",
                user=self.normal_user,
                prepare=self.prepare_audio,
                expected=ExpectedResult(
                    response_validators=[
                        self.phone_only,
                        self.json_key_equals("media_mode", "audio"),
                    ]
                ),
            ),
            RequestScenario(
                name="Phone rejects video",
                method="POST",
                user=self.normal_user,
                prepare=self.prepare_video,
                expected=ExpectedResult(status_code=400),
            ),
        ]
